from __future__ import annotations

from enum import Enum
from typing import Dict, List, Optional

from pydantic import BaseModel, Field


class Domain(str, Enum):
    ENTERPRISE = "enterprise"
    MOBILE = "mobile"
    ICS = "ics"


class Tactic(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    description: str
    domain: Domain
    url: Optional[str] = None


class SubTechnique(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    description: str
    parent_id: str
    tactic_ids: List[str]
    platforms: List[str]
    data_sources: List[str]
    mitigations: List[str]
    detection: Optional[str] = None
    domain: Domain
    is_subtechnique: bool = True
    url: Optional[str] = None
    kill_chain: List[Dict[str, str]] = Field(default_factory=list)


class Technique(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    description: str
    tactic_ids: List[str]
    platforms: List[str]
    data_sources: List[str]
    mitigations: List[str]
    subtechniques: List[str] = Field(default_factory=list)
    detection: Optional[str] = None
    domain: Domain
    is_subtechnique: bool = False
    url: Optional[str] = None
    kill_chain: List[Dict[str, str]] = Field(default_factory=list)


class Group(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    aliases: List[str]
    description: str
    techniques: List[str]
    software: List[str]
    domain: Domain
    url: Optional[str] = None


class Software(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    software_type: str
    platforms: List[str]
    techniques: List[str]
    description: str
    domain: Domain
    url: Optional[str] = None


class Mitigation(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    description: str
    techniques: List[str]
    domain: Domain
    url: Optional[str] = None


class DataSource(BaseModel):
    stix_id: str
    attack_id: str
    name: str
    description: str
    components: List[str]
    techniques: List[str]
    domain: Domain
    url: Optional[str] = None


class ATTACKMapping(BaseModel):
    """
    Reusable mapping block - attach to any detection finding, alert, or artifact.
    """

    tactic_id: str
    tactic_name: str
    technique_id: str
    technique_name: str
    subtechnique_id: Optional[str] = None
    subtechnique_name: Optional[str] = None
    domain: Domain
    confidence: float = Field(ge=0.0, le=1.0)
    data_sources: List[str] = Field(default_factory=list)
    platforms: List[str] = Field(default_factory=list)
    url: Optional[str] = None
    source_technique_id: Optional[str] = None
    resolved_technique_id: Optional[str] = None
    parent_technique_id: Optional[str] = None
    parent_technique_name: Optional[str] = None
    was_normalized: bool = False
    was_revoked: bool = False
